            (KeyCode::Char('b'), KeyModifiers::SHIFT),
            (KeyCode::Char('!'), KeyModifiers::SHIFT),
            (KeyCode::Char('c'), KeyModifiers::NONE),
        ] {
            assert!(composer.handle_key(KeyEvent::new(code, modifiers)));
        }

        assert_eq!(composer.input(), "AB!c");
    }

